CREATE TABLE actions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), recommendation_id uuid, action_type text NOT NULL, payload jsonb NOT NULL DEFAULT '{}'::jsonb, risk_level text NOT NULL CHECK(risk_level IN ('LOW','MEDIUM','HIGH')), requires_approval boolean NOT NULL DEFAULT true, approved_by uuid, status text NOT NULL DEFAULT 'SUGGESTED' CHECK(status IN ('SUGGESTED','AWAITING_APPROVAL','APPROVED','REJECTED','EXECUTED','FAILED')), created_at timestamptz NOT NULL DEFAULT now(), executed_at timestamptz, FOREIGN KEY (organization_id,recommendation_id) REFERENCES ai_recommendations(organization_id,id), FOREIGN KEY (organization_id,approved_by) REFERENCES users(organization_id,id)); CREATE INDEX actions_org_status_idx ON actions(organization_id,status);
